-- Generated by scripts/generate_estate_workbook_import.py from Archero Workers, Estate.xlsx
-- sha256 c78d56ad6b8be09a9fdaad895616bede2f9be555591101274099a932f2dbef8d. 29 workers, 13 buildings,
-- 14 building level tracks, 3 cost tables. Everything stays unreviewed.
-- Workbook note: Resource extraction is indicated without taking into account upgraded stars and bonuses from workers.
create table estate_source_workers (
  id uuid primary key default gen_random_uuid(),
  source_record_id uuid not null unique references source_records(id) on delete restrict,
  source_row_start integer not null check (source_row_start > 0),
  source_row_end integer not null check (source_row_end >= source_row_start),
  worker_name text not null,
  star_stats jsonb not null default '[]'::jsonb
);

create table estate_source_buildings (
  id uuid primary key default gen_random_uuid(),
  source_record_id uuid not null unique references source_records(id) on delete restrict,
  source_row_start integer not null check (source_row_start > 0),
  source_row_end integer not null check (source_row_end >= source_row_start),
  building_name text not null,
  building_stat text not null,
  promotion_stats jsonb not null default '[]'::jsonb
);

create table estate_source_building_levels (
  id uuid primary key default gen_random_uuid(),
  source_record_id uuid not null unique references source_records(id) on delete restrict,
  source_row_start integer not null check (source_row_start > 0),
  source_row_end integer not null check (source_row_end >= source_row_start),
  building_name text not null,
  stat_name text not null,
  stat_by_level jsonb not null default '{}'::jsonb,
  production_by_level jsonb not null default '{}'::jsonb,
  cost_by_level jsonb not null default '{}'::jsonb
);

create table estate_source_cost_tables (
  id uuid primary key default gen_random_uuid(),
  source_record_id uuid not null unique references source_records(id) on delete restrict,
  sheet_name text not null,
  source_row integer not null check (source_row > 0),
  label text not null,
  cost_values jsonb not null
);

alter table estate_source_workers enable row level security;
create policy "Admins can manage estate source workers" on estate_source_workers
for all to authenticated using (is_admin()) with check (is_admin());

alter table estate_source_buildings enable row level security;
create policy "Admins can manage estate source buildings" on estate_source_buildings
for all to authenticated using (is_admin()) with check (is_admin());

alter table estate_source_building_levels enable row level security;
create policy "Admins can manage estate source building levels" on estate_source_building_levels
for all to authenticated using (is_admin()) with check (is_admin());

alter table estate_source_cost_tables enable row level security;
create policy "Admins can manage estate source cost tables" on estate_source_cost_tables
for all to authenticated using (is_admin()) with check (is_admin());

