insert into estate_source_workers (source_record_id, source_row_start, source_row_end, worker_name, star_stats)
select source_records.id, parsed.source_row_start, parsed.source_row_end, parsed.worker_name, parsed.star_stats
from parsed
join catalog_sources on catalog_sources.name = 'User-supplied Archero workbooks'
join source_records
  on source_records.catalog_source_id = catalog_sources.id
  and source_records.external_key = parsed.external_key
  and source_records.entity_type = 'estate_source_worker'
on conflict (source_record_id) do update
set source_row_start = excluded.source_row_start, source_row_end = excluded.source_row_end, worker_name = excluded.worker_name, star_stats = excluded.star_stats;

