insert into estate_source_buildings (source_record_id, source_row_start, source_row_end, building_name, building_stat, promotion_stats)
select source_records.id, parsed.source_row_start, parsed.source_row_end, parsed.building_name, parsed.building_stat, parsed.promotion_stats
from parsed
join catalog_sources on catalog_sources.name = 'User-supplied Archero workbooks'
join source_records
  on source_records.catalog_source_id = catalog_sources.id
  and source_records.external_key = parsed.external_key
  and source_records.entity_type = 'estate_source_building'
on conflict (source_record_id) do update
set source_row_start = excluded.source_row_start, source_row_end = excluded.source_row_end, building_name = excluded.building_name, building_stat = excluded.building_stat, promotion_stats = excluded.promotion_stats;

