insert into estate_source_building_levels (source_record_id, source_row_start, source_row_end, building_name, stat_name, stat_by_level, production_by_level, cost_by_level)
select source_records.id, parsed.source_row_start, parsed.source_row_end, parsed.building_name, parsed.stat_name, parsed.stat_by_level, parsed.production_by_level, parsed.cost_by_level
from parsed
join catalog_sources on catalog_sources.name = 'User-supplied Archero workbooks'
join source_records
  on source_records.catalog_source_id = catalog_sources.id
  and source_records.external_key = parsed.external_key
  and source_records.entity_type = 'estate_source_building_levels'
on conflict (source_record_id) do update
set source_row_start = excluded.source_row_start, source_row_end = excluded.source_row_end, building_name = excluded.building_name, stat_name = excluded.stat_name, stat_by_level = excluded.stat_by_level, production_by_level = excluded.production_by_level, cost_by_level = excluded.cost_by_level;

